{
	"name": "versionless-workspace",
	"version": "0.0.0",
	"private": true,
	"license": "MIT",
	"type": "module",
	"scripts": {
		"build": "vp pack",
		"fmt": "vp fmt",
		"lint": "vp lint",
		"test": "vp test --project node",
		"fixture:ingest": "node --experimental-strip-types packages/cli/src/cli.ts fixture:ingest",
		"fixture:verify": "node --experimental-strip-types packages/cli/src/cli.ts fixture:verify",
		"receipt:verify": "node --experimental-strip-types packages/cli/src/cli.ts receipt:verify",
		"corpus:verify": "node --experimental-strip-types packages/cli/src/cli.ts corpus:verify",
		"script-surface:verify": "node --experimental-strip-types packages/cli/src/cli.ts script-surface:verify",
		"runtime-script-observation:verify": "node --experimental-strip-types packages/cli/src/cli.ts runtime-script-observation:verify",
		"trust:ingest": "node --experimental-strip-types packages/cli/src/cli.ts trust:ingest",
		"trust:generate": "node --experimental-strip-types packages/cli/src/cli.ts trust:generate",
		"trust:verify": "node --experimental-strip-types packages/cli/src/cli.ts trust:verify"
	},
	"devDependencies": {
		"@angular/compiler": "22.1.0",
		"@async/witness": "link:../witness",
		"@types/node": "24.12.2",
		"magic-regexp": "^0.11.0",
		"pathe": "^2.0.3",
		"playwright": "1.58.2",
		"typescript": "5.9.3",
		"ufo": "^1.6.4",
		"vite": "8.0.16",
		"vite-plus": "0.1.20",
		"vitest": "4.1.5",
		"yuku-analyzer": "0.7.0",
		"yuku-parser": "0.7.0"
	},
	"engines": {
		"node": ">=22"
	},
	"packageManager": "pnpm@10.33.2"
}
---WORKSPACE---
packages:
    - packages/*
    - packages/frameworks/*

catalogs:
    default:
        '@types/node': 24.12.2
        typescript: 5.9.3
        vite: 8.0.16
        vitest: 4.1.5
---VITE---
import { char, createRegExp, exactly, maybe } from 'magic-regexp';
import { MagicRegExpTransformPlugin } from 'magic-regexp/transform';
import { join } from 'pathe';
import { defineConfig } from 'vite-plus';
import type { PackUserConfig } from 'vite-plus/pack';

const rootDir = import.meta.dirname;
const external = (name: string) =>
	createRegExp(
		exactly(name)
			.at.lineStart()
			.and(maybe(exactly('/'), char.times.any()))
			.at.lineEnd(),
	);
const nodeBuiltin = createRegExp(
	exactly('node:').at.lineStart().and(char.times.any()).at.lineEnd(),
);

const pack = (
	packagePath: string,
	name: string,
	dependencies: readonly string[] = [],
	options: Partial<PackUserConfig> = {},
): PackUserConfig => ({
	name,
	cwd: join(rootDir, packagePath),
	entry: { index: './src/index.ts' },
	format: ['esm'],
	outDir: './dist',
	platform: 'node',
	fixedExtension: false,
	dts: false,
	clean: true,
	deps: { neverBundle: [nodeBuiltin, ...dependencies.map(external)], onlyBundle: false },
	...options,
});

export default defineConfig({
	plugins: [MagicRegExpTransformPlugin.vite()],
	staged: { '*': 'vp check --fix' },
	pack: [
		pack('packages/core', '@versionless/core', ['yuku-analyzer']),
		pack('packages/trust', '@versionless/trust', ['@versionless/core']),
		pack('packages/frameworks/react', '@versionless/react', ['yuku-analyzer']),
		pack('packages/frameworks/nextjs', '@versionless/nextjs'),
		pack('packages/frameworks/angular', '@versionless/angular', [
			'@angular/compiler',
			'yuku-analyzer',
		]),
		pack('packages/frameworks/angularjs', '@versionless/angularjs', ['yuku-analyzer']),
		pack(
			'packages/cli',
			'versionless',
			['@angular/compiler', '@async/witness', 'playwright', 'yuku-analyzer'],
			{
				entry: { index: './src/index.ts', cli: './src/cli.ts' },
			},
		),
		pack('packages/experiments', '@versionless/experiments', [
			'@angular/compiler',
			'yuku-analyzer',
			'yuku-parser',
		]),
		pack('packages/node-guard', '@versionless/node-guard', [], {
			format: ['cjs'],
			fixedExtension: true,
		}),
	],
	test: {
		projects: [
			{
				test: {
					name: 'node',
					environment: 'node',
					testTimeout: 120_000,
					hookTimeout: 120_000,
					include: [
						'packages/*/test/**/*.test.ts',
						'packages/frameworks/*/test/**/*.test.ts',
					],
				},
			},
		],
	},
	lint: {
		ignorePatterns: [
			'node_modules/**',
			'**/dist/**',
			'.versionless/**',
			'docs/**',
			'evidence/**',
		],
	},
	fmt: {
		useTabs: true,
		tabWidth: 4,
		printWidth: 100,
		endOfLine: 'lf',
		singleQuote: true,
		ignorePatterns: [
			'node_modules/**',
			'**/dist/**',
			'.versionless/**',
			'docs/**',
			'evidence/**',
			'pnpm-lock.yaml',
			'fixtures/**',
		],
	},
});

