1	import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
2	import { createRequire } from 'node:module';
3	import {
4		charIn,
5		createRegExp,
6		exactly,
7		global,
8		maybe,
9		oneOrMore,
10		whitespace,
11		wordChar,
12	} from 'magic-regexp';
13	import * as path from 'pathe';
14	import { analyze } from 'yuku-analyzer';
15	
16	/**
17	 * Reusable create-react-app compatibility capabilities for a Vite build.
18	 *
19	 * Every export here is application agnostic: the shapes handled are the ones
20	 * create-react-app itself defines (HTML template placeholders, `process.env`
21	 * inlining, the ambient `global` identifier, webpack's automatic Node core
22	 * module polyfills, webpack's sloppy-mode CommonJS module wrapper, webpack
23	 * tilde specifiers, and the copied public directory). No capability branches on
24	 * an application name, revision, or source string.
25	 */
26	
27	export type CraEnvironment = Readonly<Record<string, string>>;
28	
29	const templatePlaceholder = createRegExp(
30		exactly('%').and(oneOrMore(wordChar).groupedAs('key')).and('%'),
31		[global],
32	);
33	
34	const tildePrefixedCssImport = createRegExp(
35		exactly('@import')
36			.and(oneOrMore(whitespace))
37			.and(maybe(exactly('url').and(maybe(whitespace)).and('(').and(maybe(whitespace))))
38			.and(charIn(`'"`))
39			.and('~'),
40		[global],
41	);
42	
43	const closingBodyTag = createRegExp(
44		exactly('<').and(maybe(whitespace)).and('/').and(maybe(whitespace)).and('body'),
45	);
46	
47	export function compareUtf16CodeUnits(left: string, right: string): number {
48		if (left === right) return 0;
49		return left < right ? -1 : 1;
50	}
51	
52	/**
53	 * Replace `%KEY%` template placeholders the way create-react-app's
54	 * InterpolateHtmlPlugin does: only keys present in the environment are
55	 * substituted, and unknown placeholders are preserved verbatim.
56	 */
57	export function substituteCraTemplatePlaceholders(
58		template: string,
59		environment: CraEnvironment,
60	): string {
61		return template.replace(templatePlaceholder, (match: string, key: string) =>
62			Object.hasOwn(environment, key) ? (environment[key] as string) : match,
63		);
64	}
65	
66	export type CraEntryDocumentOptions = Readonly<{
67		template: string;
68		entryModule: string;
69		environment?: CraEnvironment;
70		bootstrapModules?: readonly string[];
71	}>;
72	
73	/**
74	 * Turn a create-react-app `public/index.html` template into a Vite entry
75	 * document: placeholders are substituted and the application entry is injected
76	 * as a module script immediately before the closing body tag.
77	 *
78	 * `bootstrapModules` are imported by inline module scripts placed ahead of the
79	 * application entry. Module scripts evaluate in document order, so a bootstrap
80	 * listed here runs before the first application module — the position webpack
81	 * used for the bindings it injected into every module. Omitting the option
82	 * leaves the document byte-identical to one produced without it.
83	 */
84	export function craEntryDocument(options: CraEntryDocumentOptions): string {
85		const substituted = substituteCraTemplatePlaceholders(
86			options.template,
87			options.environment ?? {},
88		);
89		const bootstrap = (options.bootstrapModules ?? [])
90			.map((module) => `<script type="module">import ${JSON.stringify(module)};</script>\n  `)
91			.join('');
92		const script = `${bootstrap}<script type="module" src="${options.entryModule}"></script>`;
93		const match = closingBodyTag.exec(substituted);
94		if (!match) return `${substituted}${substituted.endsWith('\n') ? '' : '\n'}${script}\n`;
95		return `${substituted.slice(0, match.index)}  ${script}\n  ${substituted.slice(match.index)}`;
96	}
97	
98	/**
99	 * Build the `define` map create-react-app's DefinePlugin provides: one entry per
100	 * environment key plus the whole `process.env` object for dynamic access.
101	 */
102	export function craProcessEnvironmentDefines(
103		environment: CraEnvironment,
104	): Readonly<Record<string, string>> {
105		const keys = Object.keys(environment).sort(compareUtf16CodeUnits);
106		const sorted = Object.fromEntries(keys.map((key) => [key, environment[key] as string]));
107		return Object.freeze({
108			...Object.fromEntries(
109				keys.map((key) => [`process.env.${key}`, JSON.stringify(environment[key])]),
110			),
111			'process.env': JSON.stringify(sorted),
112		});
113	}
114	
115	/**
116	 * The ambient identifier webpack 4 provides to every module it bundles for the
117	 * browser. webpack's runtime declares `global` itself (its `node.global`
118	 * option defaults to `true` on the webpack 4 line create-react-app 3 and 4
119	 * pin), so a dependency written against Node's `global` keeps working inside a
120	 * webpack browser bundle. Vite emits no such declaration: the same dependency
121	 * reaches the browser with a free `global` reference and throws
122	 * `ReferenceError: global is not defined` on first evaluation. Mapping the
123	 * identifier onto `globalThis` restores exactly the binding webpack supplied
124	 * and nothing else — it is a compile-time substitution of one free identifier,
125	 * so member accesses, property keys and locally bound `global` names are left
126	 * alone, and modules that never mention it emit byte-identical output.
127	 */
128	export function craGlobalIdentifierDefines(): Readonly<Record<string, string>> {
129		return Object.freeze({ global: 'globalThis' });
130	}
131	
132	export type CraDefineConfig = Readonly<{ define: Readonly<Record<string, string>> }>;
133	export type CraDefinePlugin = Readonly<{ name: string; config(): CraDefineConfig }>;
134	
135	/**
136	 * Contribute the webpack `global` binding as a Vite `define` entry. It is
137	 * contributed through the plugin's own configuration rather than asked of every
138	 * consumer, so any build that adopts the create-react-app adapter inherits the
139	 * ambient identifier its bundler used to provide.
140	 */
141	export function createCraGlobalIdentifierPlugin(): CraDefinePlugin {
142		return {
143			name: 'versionless-cra-global-identifier',
144			config() {
145				return { define: craGlobalIdentifierDefines() };
146			},
147		};
148	}
149	
150	/**
151	 * webpack 4's automatic Node core module resolution table, reproduced verbatim
152	 * from the `node-libs-browser` package webpack 4 depends on.
153	 *
154	 * webpack 4 resolved a bare `require('stream')` in browser builds to a browser
155	 * shim package rather than to a Node builtin, so dependencies written against
156	 * Node's standard library kept working unchanged inside a create-react-app
157	 * bundle. Vite performs no such substitution: it treats every Node builtin as
158	 * an external and emits a `__vite-browser-external` stub, so the same
159	 * `require('stream')` yields `undefined` and the first dependency that reads a
160	 * property off it fails at load — `readable-stream` 1.x, for instance, throws
161	 * `TypeError: Object prototype may only be an Object or null: undefined` from
162	 * `inherits`.
163	 *
164	 * The entries `node-libs-browser` maps to `null` (`fs`, `net`, `child_process`,
165	 * `dns`, `dgram`, `tls`, `cluster`, `module`, `readline`, `repl`) are absent
166	 * here on purpose: webpack emitted an empty module for those and Vite's own
167	 * browser-external stub already occupies that role, so nothing is claimed about
168	 * them.
169	 */
170	export const craWebpackNodeCoreShimSpecifiers: Readonly<Record<string, string>> = Object.freeze({
171		_stream_duplex: 'readable-stream/duplex.js',
172		_stream_passthrough: 'readable-stream/passthrough.js',
173		_stream_readable: 'readable-stream/readable.js',
174		_stream_transform: 'readable-stream/transform.js',
175		_stream_writable: 'readable-stream/writable.js',
176		assert: 'assert/',
177		buffer: 'buffer/',
178		console: 'console-browserify',
179		constants: 'constants-browserify',
180		crypto: 'crypto-browserify',
181		domain: 'domain-browser',
182		events: 'events/',
183		http: 'stream-http',
184		https: 'https-browserify',
185		os: 'os-browserify/browser.js',
186		path: 'path-browserify',
187		process: 'process/browser.js',
188		punycode: 'punycode/',
189		querystring: 'querystring-es3/',
190		stream: 'stream-browserify',
191		string_decoder: 'string_decoder/',
192		sys: 'util/util.js',
193		timers: 'timers-browserify',
194		tty: 'tty-browserify',
195		url: 'url/',
196		util: 'util/util.js',
197		vm: 'vm-browserify',
198		zlib: 'browserify-zlib',
199	});
200	
201	const nodeProtocolPrefix = 'node:';
202	
203	/**
204	 * The core module name a bare import specifier asks for, or `null` when the
205	 * specifier is not one webpack 4 polyfilled. Both `stream` and `node:stream`
206	 * name the same module.
207	 */
208	export function craNodeCoreModuleName(source: string): string | null {
209		const bare = source.startsWith(nodeProtocolPrefix)
210			? source.slice(nodeProtocolPrefix.length)
211			: source;
212		return Object.hasOwn(craWebpackNodeCoreShimSpecifiers, bare) ? bare : null;
213	}
214	
215	/** The package a shim specifier belongs to, for a diagnosable failure. */
216	export function craNodeCoreShimPackage(specifier: string): string {
217		const segments = specifier.split('/').filter((segment) => segment.length > 0);
218		const first = segments[0] ?? specifier;
219		return first.startsWith('@') && segments.length > 1
220			? `${first}/${segments[1] as string}`
221			: first;
222	}
223	
224	/** Resolve a bare specifier to a file, the way a require from a directory would. */
225	export type CraModuleResolver = (specifier: string) => string;
226	
227	/**
228	 * A resolver that searches the application's own dependency closure, which is
229	 * what webpack 4 did: the shim packages arrive through react-scripts' transitive
230	 * closure and are resolved against the application being compiled, never against
231	 * the build tool's own installation.
232	 */
233	export function craApplicationModuleResolver(applicationRoot: string): CraModuleResolver {
234		const applicationRequire = createRequire(
235			path.join(path.resolve(applicationRoot), 'package.json'),
236		);
237		return (specifier) => applicationRequire.resolve(specifier);
238	}
239	
240	/**
241	 * Resolve one Node core module to its webpack 4 browser shim. A shim missing
242	 * from the application's closure is a hard failure naming the module, the
243	 * package webpack would have used, and where it was searched — never a silent
244	 * stub, because a silent stub is the defect this capability exists to remove.
245	 */
246	export function resolveCraNodeCoreModule(
247		module: string,
248		resolver: CraModuleResolver,
249		origin: string,
250	): string {
251		const specifier = craWebpackNodeCoreShimSpecifiers[module];
252		if (specifier === undefined)
253			throw new Error(`Node core module "${module}" has no webpack 4 browser shim`);
254		try {
255			return resolver(specifier);
256		} catch {
257			throw new Error(
258				`create-react-app compatibility: this build imports the Node core module "${module}", ` +
259					`which webpack 4 resolved to the browser shim "${specifier}". The package ` +
260					`"${craNodeCoreShimPackage(specifier)}" is absent from the application dependency ` +
261					`closure at ${origin}, so "${module}" cannot be provided and would reach the browser ` +
262					`as an undefined stub. Install it into that closure or drop the import.`,
263			);
264		}
265	}
266	
267	/**
268	 * The identifiers webpack 4 injected into every module it bundled for the
269	 * browser, and the core module each one is sourced from. `node.process`,
270	 * `node.Buffer` and `node.setImmediate` all default to `true` on the webpack 4
271	 * line create-react-app pins, so a dependency that reads `process.nextTick`,
272	 * constructs a `Buffer`, or calls `setImmediate` keeps working with no import.
273	 * Vite injects nothing, so those same references reach the browser free and the
274	 * first one evaluated throws `ReferenceError: process is not defined`.
275	 *
276	 * The bootstrap module below installs exactly these bindings, sourced from the
277	 * same shim packages the resolution table names, and it is evaluated before the
278	 * application entry. `global` is not listed: it is already supplied as a
279	 * compile-time substitution by the global identifier capability.
280	 */
281	export const craWebpackNodeInjectedGlobals: Readonly<Record<string, string>> = Object.freeze({
282		Buffer: 'buffer',
283		clearImmediate: 'timers',
284		process: 'process',
285		setImmediate: 'timers',
286	});
287	
288	/** The module id an entry document imports to install webpack's injected globals. */
289	export const craNodeGlobalsModuleId = 'virtual:versionless-cra-node-globals';
290	
291	const resolvedNodeGlobalsModuleId = `\0${craNodeGlobalsModuleId}`;
292	
293	/**
294	 * Source for the injected-globals bootstrap, built from files already resolved
295	 * out of the application's own closure. Assignment is conditional so a host that
296	 * genuinely provides one of these names keeps it.
297	 */
298	export function craNodeGlobalsBootstrapSource(
299		files: Readonly<{ process: string; buffer: string; timers: string }>,
300	): string {
301		return [
302			`import craProcess from ${JSON.stringify(files.process)};`,
303			`import craBuffer from ${JSON.stringify(files.buffer)};`,
304			`import craTimers from ${JSON.stringify(files.timers)};`,
305			'globalThis.process ??= craProcess;',
306			'globalThis.Buffer ??= craBuffer.Buffer;',
307			'globalThis.setImmediate ??= craTimers.setImmediate;',
308			'globalThis.clearImmediate ??= craTimers.clearImmediate;',
309			'',
310		].join('\n');
311	}
312	
313	export type CraResolvedRootConfig = Readonly<{ root: string }>;
314	export type CraNodeCoreModulePlugin = Readonly<{
315		name: string;
316		enforce: 'pre';
317		configResolved(config: CraResolvedRootConfig): void;
318		resolveId(source: string): string | null;
319		load(id: string): string | null;
320	}>;
321	
322	export type CraNodeCoreModuleOptions = Readonly<{ applicationRoot?: string }>;
323	
324	/**
325	 * Provide webpack 4's Node core module polyfills to a Vite build. Resolution is
326	 * lazy — a core module is only resolved when the module graph actually asks for
327	 * it — so an application that imports nothing from the standard library pays
328	 * nothing and cannot be failed by a shim it never needed.
329	 */
330	export function createCraNodeCoreModulePlugin(
331		options: CraNodeCoreModuleOptions = {},
332	): CraNodeCoreModulePlugin {
333		let applicationRoot = options.applicationRoot ?? '';
334		let resolver: CraModuleResolver | null = null;
335		const resolve = (module: string): string => {
336			if (!applicationRoot)
337				throw new Error('CRA node core module resolution has no application root');
338			resolver ??= craApplicationModuleResolver(applicationRoot);
339			return resolveCraNodeCoreModule(module, resolver, applicationRoot);
340		};
341		return {
342			name: 'versionless-cra-node-core-modules',
343			enforce: 'pre',
344			configResolved(config) {
345				if (!options.applicationRoot) applicationRoot = config.root;
346				resolver = null;
347			},
348			resolveId(source) {
349				if (source === craNodeGlobalsModuleId) return resolvedNodeGlobalsModuleId;
350				const module = craNodeCoreModuleName(source);
351				return module === null ? null : resolve(module);
352			},
353			load(id) {
354				if (id !== resolvedNodeGlobalsModuleId) return null;
355				return craNodeGlobalsBootstrapSource({
356					buffer: resolve('buffer'),
357					process: resolve('process'),
358					timers: resolve('timers'),
359				});
360			},
361		};
362	}
363	
364	/**
365	 * Rewrite webpack's tilde-prefixed bare specifiers in CSS `@import` rules to
366	 * plain bare specifiers, which Vite resolves through node resolution.
367	 */
368	export function rewriteWebpackTildeCssImports(code: string): string {
369		return code.replace(tildePrefixedCssImport, (match: string) => match.slice(0, -1));
370	}
371	
372	function pathWithoutQuery(id: string): string {
373		const index = id.indexOf('?');
374		return index === -1 ? id : id.slice(0, index);
375	}
376	
377	export type CraTransformResult = Readonly<{ code: string; map: null }>;
378	export type CraTransformPlugin = Readonly<{
379		name: string;
380		enforce: 'pre';
381		transform(code: string, id: string): CraTransformResult | null;
382	}>;
383	
384	export function createCraTildeCssImportPlugin(): CraTransformPlugin {
385		return {
386			name: 'versionless-cra-tilde-css-import',
387			enforce: 'pre',
388			transform(code, id) {
389				if (path.extname(pathWithoutQuery(id)) !== '.css') return null;
390				const rewritten = rewriteWebpackTildeCssImports(code);
391				return rewritten === code ? null : { code: rewritten, map: null };
392			},
393		};
394	}
395	
396	/**
397	 * webpack 4 evaluated every non-harmony module inside a plain function wrapper
398	 * — `function (module, exports, __webpack_require__) { … }` — in the enclosing
399	 * bundle's mode. The bundles create-react-app 3 and 4 emit carry no `"use
400	 * strict"` prologue for those wrappers, so a CommonJS dependency ran in
401	 * sloppy mode: an assignment to an undeclared name silently created a property
402	 * on the global object, and every later reference to that name — in the same
403	 * module or in any other — read it back off the global object.
404	 *
405	 * Vite emits ECMAScript modules, and module code is always strict. The same
406	 * assignment is now a write to an unresolvable reference, which throws
407	 * `ReferenceError: <name> is not defined` the moment the module is evaluated,
408	 * long before the application can mount.
409	 *
410	 * The capability below restores webpack's tolerance without unpicking strict
411	 * mode anywhere. A dependency module that webpack would have wrapped in sloppy
412	 * mode is scanned for exactly the names it assigns without declaring; for each
413	 * one a prelude creates the property on `globalThis` if nothing already holds
414	 * it. Strict mode only rejects assignments to references it cannot resolve, and
415	 * a property of the global object is resolvable, so the original assignment
416	 * evaluates unchanged — and, because the binding lives on the global object
417	 * rather than in the module, cross-module reads of the same name find the same
418	 * value webpack's implicit global gave them.
419	 *
420	 * Three properties matter, and each is enforced rather than asserted:
421	 *
422	 * - Application source is untouched. Only modules under a dependency directory
423	 *   are scanned, so first-party code keeps every strict-mode diagnostic.
424	 * - Harmony modules are untouched. webpack made those strict too, so a module
425	 *   carrying `import`/`export` is left exactly as it is.
426	 * - A module that cannot be analysed is a hard failure naming the module and
427	 *   the diagnostic, never a silent skip.
428	 */
429	
430	const dependencyDirectorySegment = 'node_modules';
431	
432	/**
433	 * The extensions webpack 4 fed through its sloppy CommonJS wrapper. `.mjs` is
434	 * absent on purpose: webpack forced those to harmony, hence to strict mode.
435	 */
436	const sloppyCommonJsExtensions: ReadonlySet<string> = new Set(['.js', '.cjs', '']);
437	
438	/** True when a module id lies inside a dependency directory. */
439	export function craIsDependencyModule(id: string): boolean {
440		return path.normalize(id).split('/').includes(dependencyDirectorySegment);
441	}
442	
443	export type CraSloppyModuleKind = 'sloppy-commonjs' | 'ecmascript-module' | 'unanalyzable';
444	
445	export type CraImplicitGlobalScan = Readonly<{
446		kind: CraSloppyModuleKind;
447		names: readonly string[];
448		diagnostics: readonly string[];
449	}>;
450	
451	/**
452	 * Classify a module the way webpack 4 did and, when it is one of the sloppy
453	 * CommonJS modules, report the names it assigns without ever declaring them.
454	 *
455	 * The scan rides a real scope resolution: a name counts only when a write
456	 * reference resolves to no binding in any enclosing scope, so a local variable,
457	 * a parameter, a `catch` binding or a hoisted `var` of the same name elsewhere
458	 * in the module never produces a false report, and a shadowed inner name never
459	 * hides a genuine implicit global.
460	 */
461	export function scanCraImplicitGlobals(code: string, id = 'dependency.js'): CraImplicitGlobalScan {
462		const script = analyze(code, { path: id, lang: 'js', sourceType: 'script' });
463		const scriptErrors = script.diagnostics.filter((entry) => entry.severity === 'error');
464		if (scriptErrors.length > 0) {
465			// Harmony syntax is the ordinary reason a script parse fails, and webpack
466			// ran those modules in strict mode as well. Anything that parses as
467			// neither is a module this capability cannot reason about.
468			const esm = analyze(code, { path: id, lang: 'js', sourceType: 'module' });
469			const esmErrors = esm.diagnostics.filter((entry) => entry.severity === 'error');
470			return esmErrors.length === 0
471				? Object.freeze({ kind: 'ecmascript-module', names: [], diagnostics: [] })
472				: Object.freeze({
473						kind: 'unanalyzable',
474						names: [],
475						diagnostics: esmErrors.map((entry) => entry.message),
476					});
477		}
478		if (script.imports.length > 0 || script.exports.length > 0)
479			return Object.freeze({ kind: 'ecmascript-module', names: [], diagnostics: [] });
480		const names = new Set<string>();
481		for (const reference of script.unresolvedReferences)
482			if (reference.isWrite) names.add(reference.name);
483		return Object.freeze({
484			kind: 'sloppy-commonjs',
485			names: [...names].sort(compareUtf16CodeUnits),
486			diagnostics: [],
487		});
488	}
489	
490	/**
491	 * The prelude that gives a sloppy-mode implicit global its binding. Creating
492	 * the property is conditional, so a name the host genuinely owns — or one an
493	 * earlier dependency already assigned — keeps the value it has; only the
494	 * binding webpack's global object would have carried is added.
495	 */
496	export function craImplicitGlobalPrelude(names: readonly string[]): string {
497		if (names.length === 0) return '';
498		const statements = names
499			.map((name) => {
500				const key = JSON.stringify(name);
501				return `if (!(${key} in globalThis)) globalThis[${key}] = void 0;`;
502			})
503			.join(' ');
504		return `/* webpack sloppy-mode implicit globals */ ${statements}`;
505	}
506	
507	/**
508	 * The module source with its implicit-global prelude installed. The prelude
509	 * occupies no line of its own — it is appended to the first line — so every
510	 * line number in the original module, and therefore every source map that
511	 * refers to it, still points where it did. A hashbang keeps the first line.
512	 */
513	export function craSloppyCommonJsSource(code: string, names: readonly string[]): string {
514		const prelude = craImplicitGlobalPrelude(names);
515		if (prelude === '') return code;
516		if (!code.startsWith('#!')) return `${prelude}${code}`;
517		const firstLineEnd = code.indexOf('\n');
518		if (firstLineEnd === -1) return `${code}\n${prelude}`;
519		return `${code.slice(0, firstLineEnd + 1)}${prelude}${code.slice(firstLineEnd + 1)}`;
520	}
521	
522	export type CraImplicitGlobalRecord = Readonly<{ id: string; names: readonly string[] }>;
523	
524	export type CraSloppyCommonJsGlobalsOptions = Readonly<{
525		observe?: (record: CraImplicitGlobalRecord) => void;
526	}>;
527	
528	/**
529	 * Reproduce webpack 4's sloppy-mode CommonJS wrapper for dependency modules.
530	 * A module that declares everything it assigns is returned untouched, so a
531	 * dependency closure with no implicit globals emits byte-identical output.
532	 */
533	export function createCraSloppyCommonJsGlobalsPlugin(
534		options: CraSloppyCommonJsGlobalsOptions = {},
535	): CraTransformPlugin {
536		return {
537			name: 'versionless-cra-sloppy-commonjs-globals',
538			enforce: 'pre',
539			transform(code, id) {
540				const file = pathWithoutQuery(id);
541				if (!craIsDependencyModule(file)) return null;
542				if (!sloppyCommonJsExtensions.has(path.extname(file))) return null;
543				const scan = scanCraImplicitGlobals(code, file);
544				if (scan.kind === 'unanalyzable')
545					throw new Error(
546						`create-react-app compatibility: the dependency module ${file} parses as neither ` +
547							`a script nor an ECMAScript module, so webpack 4's sloppy-mode CommonJS wrapper ` +
548							`cannot be reproduced for it and an implicit global it may rely on would reach ` +
549							`the browser as a ReferenceError. Parser diagnostics: ${scan.diagnostics.join('; ')}`,
550					);
551				if (scan.names.length === 0) return null;
552				options.observe?.({ id: file, names: scan.names });
553				return { code: craSloppyCommonJsSource(code, scan.names), map: null };
554			},
555		};
556	}
557	
558	async function filesBelow(directory: string): Promise<string[]> {
559		const files: string[] = [];
560		for (const entry of await readdir(directory, { withFileTypes: true })) {
561			const item = path.join(directory, entry.name);
562			if (entry.isDirectory()) files.push(...(await filesBelow(item)));
563			else if (entry.isFile()) files.push(item);
564		}
565		return files;
566	}
567	
568	/**
569	 * The create-react-app public directory inventory: every file below the
570	 * directory except the excluded template, as sorted relative POSIX paths.
571	 */
572	export async function craPublicAssetPaths(
573		directory: string,
574		exclude: readonly string[] = [],
575	): Promise<readonly string[]> {
576		const excluded = new Set(exclude);
577		return (await filesBelow(directory))
578			.map((file) => path.relative(directory, file).split(path.sep).join('/'))
579			.filter((file) => !excluded.has(file))
580			.sort(compareUtf16CodeUnits);
581	}
582	
583	export type CraResolvedBuildConfig = Readonly<{ build: Readonly<{ outDir: string }> }>;
584	export type CraOutputPlugin = Readonly<{
585		name: string;
586		configResolved(config: CraResolvedBuildConfig): void;
587		closeBundle: Readonly<{ order: 'post'; sequential: true; handler(): Promise<void> }>;
588	}>;
589	
590	export type CraPublicDirectoryOptions = Readonly<{
591		directory: string;
592		exclude?: readonly string[];
593	}>;
594	
595	/**
596	 * Copy the create-react-app public directory into the build output the way
597	 * `react-scripts build` does, excluding the HTML template that becomes the
598	 * bundled entry document.
599	 */
600	export function createCraPublicDirectoryPlugin(
601		options: CraPublicDirectoryOptions,
602	): CraOutputPlugin {
603		let outputDirectory = '';
604		return {
605			name: 'versionless-cra-public-directory',
606			configResolved(config) {
607				outputDirectory = path.resolve(config.build.outDir);
608			},
609			closeBundle: {
610				order: 'post',
611				sequential: true,
612				async handler() {
613					if (!outputDirectory) throw new Error('CRA public directory outDir is unresolved');
614					for (const file of await craPublicAssetPaths(
615						options.directory,
616						options.exclude ?? [],
617					)) {
618						const destination = path.join(outputDirectory, file);
619						await mkdir(path.dirname(destination), { recursive: true });
620						await writeFile(
621							destination,
622							await readFile(path.join(options.directory, file)),
623						);
624					}
625				},
626			},
627		};
628	}
629	
630	export type CraViteAdapterOptions = Readonly<{
631		publicDirectory: string;
632		templateFile?: string;
633		applicationRoot?: string;
634		observeImplicitGlobals?: (record: CraImplicitGlobalRecord) => void;
635	}>;
636	
637	export type CraViteAdapterPlugins = readonly [
638		CraTransformPlugin,
639		CraTransformPlugin,
640		CraNodeCoreModulePlugin,
641		CraDefinePlugin,
642		CraOutputPlugin,
643	];
644	
645	/**
646	 * The create-react-app compatibility plugin set: tilde CSS specifier rewriting,
647	 * webpack's sloppy-mode CommonJS wrapper for dependency modules, webpack's
648	 * automatic Node core module polyfills, the ambient `global` identifier, plus
649	 * public directory replication.
650	 */
651	export function createCraViteAdapter(options: CraViteAdapterOptions): CraViteAdapterPlugins {
652		return [
653			createCraTildeCssImportPlugin(),
654			createCraSloppyCommonJsGlobalsPlugin(
655				options.observeImplicitGlobals === undefined
656					? {}
657					: { observe: options.observeImplicitGlobals },
658			),
659			createCraNodeCoreModulePlugin(
660				options.applicationRoot === undefined
661					? {}
662					: { applicationRoot: options.applicationRoot },
663			),
664			createCraGlobalIdentifierPlugin(),
665			createCraPublicDirectoryPlugin({
666				directory: options.publicDirectory,
667				exclude: [options.templateFile ?? 'index.html'],
668			}),
669		];
670	}
